package org.apache.commons.text.similarity;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import java.nio.CharBuffer;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class LevenshteinDistance_ESTest_test06 extends LevenshteinDistance_ESTest_scaffolding {

    /**
     * Verifies that a thresholded LevenshteinDistance returns -1 when the actual
     * edit distance exceeds the threshold.
     *
     * <p>The threshold is first derived from an unlimited comparison of a sequence
     * with itself (distance 0). Re-using that 0 as the threshold for a second
     * comparison of two sequences that differ in one character (actual distance 1)
     * forces the limited algorithm to give up and return -1.</p>
     */
    @Test(timeout = 4000)
    public void distanceExceedingThresholdReturnsMinusOne() throws Throwable {
        // A two-char sequence ")�" and an all-zero two-char sequence "��".
        char[] parenThenNul = new char[2];
        parenThenNul[0] = ')';
        CharBuffer parenSequence = CharBuffer.wrap(parenThenNul);

        char[] twoNuls = new char[2];
        CharBuffer nulSequence = CharBuffer.wrap(twoNuls);

        // The default instance has no threshold; comparing a sequence with itself yields 0.
        LevenshteinDistance unlimitedDistance = LevenshteinDistance.getDefaultInstance();
        Integer selfDistance = unlimitedDistance.apply((CharSequence) parenSequence, (CharSequence) parenSequence);

        // Use that 0 as the threshold. The two sequences differ in their first character
        // (actual distance 1 > threshold 0), so the limited algorithm returns -1.
        LevenshteinDistance thresholdedDistance = new LevenshteinDistance(selfDistance);
        Integer limitedResult = thresholdedDistance.apply((CharSequence) parenSequence, (CharSequence) nulSequence);

        assertEquals(-1, (int) limitedResult);
    }
}
